def transform(grid):
    """Recolor the 4-connected zero region(s) touching the marker to marker color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 2)]
    if not markers:
        return out
    marker_color = grid[markers[0][0]][markers[0][1]]
    q = deque(markers)
    seen = set(markers)
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                if grid[nr][nc] == 0 or grid[nr][nc] == marker_color:
                    seen.add((nr, nc))
                    q.append((nr, nc))
                    if grid[nr][nc] == 0:
                        out[nr][nc] = marker_color
    return out
